head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.notiId;
scwin.strBzProcsNo, scwin.strProcsCd, scwin.strDtlSeq, scwin.reg_emp_no, scwin.strFileTpCd;
scwin.fn_SetPar;
scwin.fileType;

/**
 * @method
