/**
 * @method
 * @name read
 * @description read 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    const sbmOptions = {
        id : "sbm_trs_Read",
        action : "/RealInvstg.do",
        ref : "dts_fileList",
        target : "trs_Read=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

scwin.chkFile = async function() {
            let fileYn = "Y";
            let fileTp = "Y";
            let isOk = true;
            for (i = 1; i <= dts_fileList.getRowCount(); i++) {
                if (dts_fileList.getCellData(i, "ATTACH_FILE_NM") === "") {
                    fileYn = "N";
                }
                if ($c.ut.trim(dts_fileList.getCellData(i, "LIST_ELIGTY_FILE_TP_CD")) === "") {
                    fileTp = "N";
                }
            }
            if (fileYn === "N") {
                await $c.win.alert("첨부파일을 하나이상 등록해주세요");
                isOk = false;
            }
            if (fileTp === "N") {
                await $c.win.alert("자료유형을 선택해 주세요");
                isOk = false;
            }
            /*
            		if(dts_fileList.CountRow == 0){
            			alert("첨부파일을 한개이상  입력해주세요.");
            			isOk = false;
            		}
             */
            if (isOk) {
                let fileName = "";
                let realName = "";
                for (i = 1; i <= dts_fileList.getRowCount(); i++) {
                    fileName = dts_fileList.getCellData(i, "ATTACH_FILE_NM");
                    if (fileName.length > 0) {
                        realName = fileName.substring(fileName.lastIndexOf('\')+1);, ( !$c.lce.fn_getCheckByte(realName,realName,80) ) ,{return : return , false : false}));
                            }
                        }
                        return isOk;
                    }

                    function fn_getCheckByte(strItemNm, strVal, limitsize) {
                        var len = $c.lce.fn_getByteLength(strVal);
                        if (limitsize < len) {
                            $c.win.alert("입력된 [" + strItemNm + "]은 " + len + "Byte로 \n제한 길이인 " + limitsize + "Byte를 초과 하였습니다. ");
                            return false;
                        }
                        return true;
                    };

                    function fn_getByteLength(s) {
                        var len = 0;
                        if (s == null) return 0;
                        for (var i = 0; i < s.length; i++) {
                            var c = escape(s.charAt(i));
                            if (c.length == 1) {
                                // ASCII 코드로 구현될수 있는 영숫자인경우 ( 1Byte)
                                len++;
                            } else if (c.indexOf("%u") != -1) {
                                // 한글 및 특수문자인경우 ( DB가 UTF-8 인경우 3Byte 처리 )
                                //len += 3;
                                len += 2;
                            } else if (c.indexOf("%") != -1) {
                                // ASCII 코드로 구현될수 있는 영숫자 이외의 문자인경우 ( 1Byte)
                                len += (c.length / 3);
                            }
                        }
                        return len;
                    };

                    function fn_checkFileCnt() {
                        if (scwin.fileType == "C" || scwin.fileType == "D") {
                            var status = "";
                            var fileCnt = 0;
                            for (var i = 1, j = dts_fileList.getTotalRow(); i <= j; i++) {
                                status = dts_fileList.getRowStatus(i);
                                if (status != "2") {
                                    fileCnt++;
                                }
                                if (fileCnt > 1) {
                                    $c.win.alert("하나의 파일만 첨부할수 있습니다.");
                                    return false;
                                }
                            }
                        }
                        return true;
                    };

                    function fn_save() {
                        scwin.reg_emp_no = js_emp_no;
                        if (scwin.chkFile() && fn_checkFileCnt()) {
                            var rtn = confirm('첨부파일을 등록 하시겠습니까?');
                            if (rtn == 1) {
                                // [확인] 버튼이 눌려졌을 경우
                                if (scwin.isBefore) {
                                    scwin.strDtlSeq = "1";
                                }
                                const sbmOptions3 = {
                                    id : "sbm_trs_Save",
                                    action : "/RealInvstg.do",
                                    ref : "dts_fileList",
                                    target : "trs_Save=body.content",
                                    isProcessMsg : false
                                };

                                const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
                                // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)
                            }
                        }
                    };

                    function fn_update() {
                        scwin.reg_emp_no = js_emp_no;
                        for (i = 0; i <= dts_fileList.getTotalRow(); i++) {
                            if (dts_fileList.getCellData(i, "fileInfo") == "" && dts_fileList.getCellData(i, "ATTACH_FILE_NM") == "") {
                                $c.cp.removeRow(dts_fileList, i);
                            }
                        }
                        if (scwin.chkFile() && fn_checkFileCnt()) {
                            var rtn = confirm('첨부파일을 수정 하시겠습니까?');
                            if (rtn == 1) {
                                // [확인] 버튼이 눌려졌을 경우
                                if (scwin.isBefore) {
                                    scwin.strDtlSeq = "1";
                                }
                                const sbmOptions4 = {
                                    id : "sbm_trs_Update",
                                    action : "/RealInvstg.do",
                                    ref : "dts_fileList",
                                    target : "trs_Update=body.content",
                                    isProcessMsg : false
                                };

                                const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
                                // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)
                            }
                        }
                    };

                    function fn_delete() {
                        var rtn = confirm('모든 첨부파일을 삭제 하시겠습니까?');
                        if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

                        {

                            //dts_delRealInvstgFile.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
                            dts_delRealInvstgFile.insertRow();
                            dts_delRealInvstgFile.setCellData(1, "bz_procs_no", scwin.strBzProcsNo);
                            dts_delRealInvstgFile.setCellData(1, "list_eligty_procs_cd", scwin.strProcsCd);
                            dts_delRealInvstgFile.setCellData(1, "list_eligty_invstg_dtl_seq", scwin.strDtlSeq);
                            const sbmOptions5 = {
                                id : "sbm_trs_Delete",
                                action : "/RealInvstg.do",
                                ref : "dts_delRealInvstgFile",
                                target : "trs_Delete=body.content",
                                isProcessMsg : false
                            };

                            const sbmRtn5 = await $c.sbm.executeDynamic(sbmOptions5);
                            // TODO Stage2: sbmRtn5 응답 처리 로직 작성 (구 submitDoneHandler 자리)
                        }
                    };
                    //파일 다운로드
                    function fn_filedown(bzProcsNo, procsNo, dtlSeq, fileSeq) {
                        location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&BZ_PROCS_NO=" + bzProcsNo + "&LIST_ELIGTY_PROCS_CD=" + procsNo + "&LIST_ELIGTY_INVSTG_DTL_SEQ=" + dtlSeq + "&ATTACH_FILE_SEQ=" + fileSeq + "&gubun=42";
                    };

                    function fn_setDataHeader() {

                        //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인

                    };

                    function fn_searchCode() {
                        const sbmOptions = {
                            id : "sbm_dts_Cod",
                            action : "/CodeAction.do",
                            ref : "",
                            target : "dts_Cod=body.content",
                            isProcessMsg : false
                        };

                        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
                        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

                        var strCbdReason = ""; //초기값

                        for (k = 1; k <= dts_Cod.getTotalRow(); k++) {
                            if (scwin.fileType == "A") {
                                if (dts_Cod.getCellData(k, "VALUE") != "01" && dts_Cod.getCellData(k, "VALUE") != "02") {
                                    continue;
                                }
                            } else if (scwin.fileType == "B") {
                                if (dts_Cod.getCellData(k, "VALUE") != "06") {
                                    continue;
                                }
                            } else if (scwin.fileType == "C") {
                                if (dts_Cod.getCellData(k, "VALUE") != "07") {
                                    continue;
                                }
                            } else if (scwin.fileType == "D") {
                                if (dts_Cod.getCellData(k, "VALUE") != "08") {
                                    continue;
                                }
                            } else if (scwin.fileType == "F") {
                                if (dts_Cod.getCellData(k, "VALUE") != "01" && dts_Cod.getCellData(k, "VALUE") != "02" && dts_Cod.getCellData(k, "VALUE") != "06") {
                                    continue;
                                }
                            }
                            strCbdReason = strCbdReason + (strCbdReason == "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
                        }
                        $c.cm.setColumnProp(grd_userlist, 'LIST_ELIGTY_FILE_TP_CD', 'Data', strCbdReason);
                    };

                    function fn_parentRefresh() {
                        var fr_fn_list_sync = $c.frame.path("../").fn_afterFile;
                        fr_fn_list_sync();
                    };

                    function callElasticFileNoti(callType) {
                        $.ajax({
                            type: "POST",
                            url: "/elasticNoti.do",
                            data: {
                                method: "notiEligtyFile",
                                bz_procs_no: scwin.strBzProcsNo,
                                url: "/index/tbld_eligty_invstg_attach/kafka",
                                type: callType
                            },
                            async: true
                        });
                    };

                    function trs_Read_OnLoadError() {
                        $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
                    };

                    function trs_Save_OnSuccess() {
                        $c.win.alert($c.stf.getMessageParam("MSG-A001", "첨부파일등록"));
                        callElasticFileNoti("POST");
                        fn_parentRefresh();
                    };

                    function trs_Save_OnFail() {
                        $c.win.alert($c.stf.getMessageParam("MSG-A002", "첨부파일등록"));
                    };

                    function trs_Update_OnSuccess() {
                        $c.win.alert($c.stf.getMessageParam("MSG-A001", "첨부파일수정"));
                        callElasticFileNoti("POST");
                        fn_parentRefresh();
                    };

                    function trs_Update_OnFail() {
                        $c.win.alert($c.stf.getMessageParam("MSG-A002", "첨부파일수정"));
                    };

                    function trs_Delete_OnSuccess() {
                        $c.win.alert($c.stf.getMessageParam("MSG-A001", "첨부파일삭제"));
                        callElasticFileNoti("POST");
                        fn_parentRefresh();
                        await $c.frame.CloseFrame(); //self.close();

                    };

                    function trs_Delete_OnFail() {
                        $c.win.alert($c.stf.getMessageParam("MSG-A002", "첨부파일삭제"));
                    };

                    function grd_userlist_OnDblClick(row, colid) {
                        var bzProcsNo = dts_fileList.getCellData(row, "BZ_PROCS_NO");
                        var procsNo = dts_fileList.getCellData(row, "LIST_ELIGTY_PROCS_CD");
                        var dtlSeq = dts_fileList.getCellData(row, "LIST_ELIGTY_INVSTG_DTL_SEQ");
                        var fileSeq = dts_fileList.getCellData(row, "ATTACH_FILE_SEQ");
                        if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0) {
                            $c.elw.fn_filedown(bzProcsNo, procsNo, dtlSeq, fileSeq);
                        }
                    };

                    function btn_lineadd_onclick() {
                        dts_fileList.insertRow();
                        inf_find.open();
                        if (inf_find.getValue() != "") {
                            if (scwin.notiId == "input") {
                                dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
                                file_name.setValue(inf_find.getValue());
                            } else {
                                dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
                                file_name.setValue(inf_find.getValue());
                            }
                        } else {
                            $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
                        }
                        /*
	if(isBefore){
dts_fileList.setNameString(dts_fileList.rowposition, "LIST_ELIGTY_FILE_TP_CD","03") ;
dts_fileList.setNameString(dts_fileList.rowposition, "REMK","BEFORE") ;
grd_userlist.setColumnProp('LIST_ELIGTY_FILE_TP_CD','edit',"none") ;
	}
                         */
                        if (scwin.fileType == "B") {
                            dts_fileList.setCellData(dts_fileList.getRowPosition(), "LIST_ELIGTY_FILE_TP_CD", "06");
                        } else if (scwin.fileType == "C") {
                            dts_fileList.setCellData(dts_fileList.getRowPosition(), "LIST_ELIGTY_FILE_TP_CD", "07");
                        } else if (scwin.fileType == "D") {
                            dts_fileList.setCellData(dts_fileList.getRowPosition(), "LIST_ELIGTY_FILE_TP_CD", "08");
                        }
                    };

                    function btn_linedelete_onclick() {
                        var rtn = confirm('해당첨부파일을 삭제 하시겠습니까?');
                        if (rtn == 1) {
                            $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
                        }
                    };

                    function btn_close_onclick() {
                        fn_parentRefresh();
                        await $c.frame.CloseFrame();
                    };

                    function gform_onload() {
                        $c.stf.showObj(inf_find, false);
                        $c.cm.PanelToGroupBox(panel_Top);
                        scwin.fileType = $c.frame.path("../").scwin.fileType;
                        buttonSet.setSaveInfo(btn_save, fn_save); // 저장
                        buttonSet.setUpdateInfo(btn_modify, fn_update); // 수정
                        //buttonSet.setDeleteInfo( btn_delete, fn_delete );     // 삭제

                        setInsertReadyStatus = "I";
                        scwin.strBzProcsNo = $c.stf.getQuery(frame.srcUrl, "BZ_PROCS_NO");
                        scwin.strProcsCd = $c.stf.getQuery(frame.srcUrl, "LIST_ELIGTY_PROCS_CD");
                        scwin.strDtlSeq = $c.stf.getQuery(frame.srcUrl, "LIST_ELIGTY_INVSTG_DTL_SEQ");
                        scwin.strFileTpCd = $c.stf.getQuery(frame.srcUrl, "LIST_ELIGTY_FILE_TP_CD");
                        if (scwin.strDtlSeq == "") {
                            scwin.isBefore = true;
                        }
                        $c.elw.fn_searchCode();
                        scwin.read();

                        //기존파일이 없으면
                        if (dts_fileList.getTotalRow() == 0) {
                            buttonSet.setInsertStatus();
                            fn_setDataHeader();
                        } else {
                            buttonSet.setUpdateStatus();
                        }
                    };

                    function inf_find_OnClick() {
                        var filenm = file_name.getValue();
                        if (scwin.notiId == "input") {
                            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
                            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
                            file_name.setValue(inf_find.getValue());
                        } else {
                            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
                            //dts_fileList.NameString(dts_fileList.rowposition, "ATTACH_SEQ") = dts_fileList.rowposition;
                            file_name.setValue(inf_find.getValue());
                        }
                        if (inf_find.getValue() == "") {
                            file_name.setValue(filenm);
                        }
                    };

                    function grd_userlist_CanColumnPosChange(row, colid) {
                        return true;
                    };
                };
